package com.autoops.user.service;import com.autoops.common.security.CurrentUser;import com.autoops.user.entity.User;import com.autoops.user.repository.UserRepository;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;@Service public class UserAdminService{private final UserRepository repo;private final PasswordEncoder passwords;private final CurrentUser current;public UserAdminService(UserRepository r,PasswordEncoder p,CurrentUser c){repo=r;passwords=p;current=c;}public List<User> list(){return repo.findAll();}@Transactional public User create(String username,String password,User.Role role){if(repo.findByUsername(username).isPresent())throw new IllegalArgumentException("Username already exists");var u=new User();u.setUsername(username);u.setPasswordHash(passwords.encode(password));u.setRole(role);u.setStatus(User.Status.ACTIVE);return repo.save(u);}@Transactional public User status(Long id,User.Status status){var u=repo.findById(id).orElseThrow();if(u.getId().equals(current.id())&&u.getRole()==User.Role.ADMIN&&status!=User.Status.ACTIVE&&activeAdmins()<=1)throw new IllegalArgumentException("Cannot disable the last active administrator");u.setStatus(status);return repo.save(u);}@Transactional public void resetPassword(Long id,String password){var u=repo.findById(id).orElseThrow();u.setPasswordHash(passwords.encode(password));repo.save(u);}private long activeAdmins(){return repo.findAll().stream().filter(u->u.getRole()==User.Role.ADMIN&&u.getStatus()==User.Status.ACTIVE).count();}}
